import com.webcommander.sdk.client.ApiResponse;
import java.util.Map;

ApiResponse response = client.shoppingCart().getShoppingCart();
Map<?, ?> settings = (Map<?, ?>) ((Map<?, ?>) response.getMap()).get("shopping_cart");
Map<?, ?> cartPage = (Map<?, ?>) settings.get("cart_page");
Map<?, ?> flyingCart = (Map<?, ?>) settings.get("flying_cart");
System.out.println(cartPage.get("show_product_thumbnail") + " " + cartPage.get("save_cart"));
System.out.println(flyingCart.get("enabled") + " " + flyingCart.get("enable_clear_cart"));

